#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *L = malloc(N * sizeof(long long));
    long long sum = 0;

    for (int i = 0; i < N; i++) {
        scanf("%lld", &L[i]);
        sum += L[i];
    }

    if (sum % 2 != 0) {
        printf("N\n");
        free(L);
        return 0;
    }

    long long half = sum / 2;
    long long *pos = malloc(N * sizeof(long long));

    long long cur = 0;
    for (int i = 0; i < N; i++) {
        pos[i] = cur;
        cur += L[i];
    }

    int matches = 0;

    for (int i = 0; i < N; i++) {
        long long target = pos[i] + half;
        if (target >= sum) target -= sum;

        int lo = 0, hi = N - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (pos[mid] == target) {
                matches++;
                break;
            } else if (pos[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
    }

    if (matches >= 4) printf("S\n");
    else printf("N\n");

    free(L);
    free(pos);
    return 0;
}
